import unittest
from candidate import pairs_sum_to_zero

class TestPairsSumToZero(unittest.TestCase):
    def test_no_elements_returns_false(self):
        self.assertFalse(pairs_sum_to_zero([]))

    def test_single_element_returns_false(self):
        self.assertFalse(pairs_sum_to_zero([5]))

    def test_pair_with_zero_returns_true(self):
        self.assertTrue(pairs_sum_to_zero([1, -1]))

    def test_multiple_pairs_returns_true(self):
        self.assertTrue(pairs_sum_to_zero([2, 4, -5, 3, 5, 7]))

    def test_no_zero_sum_pair_returns_false(self):
        self.assertFalse(pairs_sum_to_zero([1, 3, 5, 0]))

    def test_duplicate_zero_elements_returns_true(self):
        self.assertTrue(pairs_sum_to_zero([0, 0, 1, 2]))

    def test_single_zero_element_returns_false(self):
        self.assertFalse(pairs_sum_to_zero([0]))

    def test_order_of_elements_does_not_affect_result(self):
        self.assertTrue(pairs_sum_to_zero([5, -5, 10]))

    def test_multiple_negative_and_positive_pairs(self):
        self.assertTrue(pairs_sum_to_zero([-2, -3, 2, 3, 4]))

    def test_list_with_floats_returns_true_when_sum_is_zero(self):
        self.assertTrue(pairs_sum_to_zero([1.5, -1.5, 2]))

    def test_list_with_floats_no_zero_sum_returns_false(self):
        self.assertFalse(pairs_sum_to_zero([1.5, 2.5, 3.5]))

    def test_none_as_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            pairs_sum_to_zero(None)

    def test_non_iterable_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            pairs_sum_to_zero(42)

    def test_list_with_none_element_raises_type_error(self):
        with self.assertRaises(TypeError):
            pairs_sum_to_zero([1, None, -1])

    def test_list_with_unhashable_element_raises_type_error(self):
        with self.assertRaises(TypeError):
            pairs_sum_to_zero([1, {}, -1])

    def test_list_with_strings_does_not_raise_error_but_returns_false(self):
        self.assertFalse(pairs_sum_to_zero(['a', 'b', 'c']))

    def test_mixed_types_raises_type_error_on_addition(self):
        with self.assertRaises(TypeError):
            pairs_sum_to_zero([1, 'a', -1])

    def test_list_with_large_numbers_returns_true(self):
        self.assertTrue(pairs_sum_to_zero([10**12, -10**12]))

    def test_list_with_negative_zero_pair_returns_true(self):
        self.assertTrue(pairs_sum_to_zero([-0, 0, 5]))

    def test_list_with_repeated_numbers_no_zero_pair_returns_false(self):
        self.assertFalse(pairs_sum_to_zero([1, 1, 1, 1]))

if __name__ == '__main__':
    unittest.main()
